package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager;import com.bedlessfighter.necroManager.managers.PermissionManager;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.jetbrains.annotations.NotNull;
public final class ClearChatCommand implements CommandExecutor {public boolean onCommand(@NotNull CommandSender s, @NotNull Command c, @NotNull String label, @NotNull String @NotNull [] a){if(a.length!=0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /clearchat");return true;}if(!PermissionManager.has(s,"necromanager.clearchat")){MessageManager.send(s,"messages.no-perm","&cYou don't have enough permissions to issue this command!");return true;}for(var p:Bukkit.getOnlinePlayers())for(int i=0;i<100;i++)p.sendMessage("");Bukkit.broadcastMessage(MessageManager.color(MessageManager.configured("messages.chat-cleared","&cChat was cleared by staff.")));return true;}}